from functools import lru_cache


def combinazioni(L, misure):
    misure = tuple(sorted(set(misure)))

    @lru_cache(maxsize=None)
    def conta(resto, i):
        if resto == 0:
            return 1
        if resto < 0 or i == len(misure):
            return 0
        return conta(resto - misure[i], i) + conta(resto, i + 1)

    return conta(L, 0)


def sfrido_minimo(L, misure):
    misure = tuple(sorted(set(misure)))

    @lru_cache(maxsize=None)
    def migliore(resto):
        opzioni = [migliore(resto - m) for m in misure if m <= resto]
        return min(opzioni) if opzioni else resto

    return migliore(L)

