from barre import combinazioni, sfrido_minimo


def test_monete():
    assert combinazioni(10, [2, 5]) == 2          # 2+2+2+2+2, 5+5
    assert combinazioni(4, [1, 2, 3]) == 4


def test_grande_e_veloce():
    assert combinazioni(6000, [250, 400, 750, 1200]) > 0


def test_sfrido():
    assert sfrido_minimo(6000, [1700, 2300]) == 300   # 2300 + 1700 + 1700 = 5700
    assert sfrido_minimo(6000, [1500, 2000]) == 0
